package com.mod.htgt6.minecraft1202.Module.Client.Exploration;
import com.mod.htgt6.minecraft1202.Module.Registry.Exploration.ExplorationContent112;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.RenderHelper;import net.minecraft.client.renderer.entity.RenderItem;import net.minecraft.item.ItemStack;import net.minecraftforge.client.event.RenderGameOverlayEvent;import org.lwjgl.opengl.GL11;
/** Forty-tick centered Totem pop matching the timing and motion of the 1.12 activation. */
public final class TotemActivationRenderer112{
 private static int ticks=-1;
 public static void activate(){ticks=0;Minecraft mc=Minecraft.getMinecraft();if(mc.thePlayer!=null){mc.thePlayer.playSound("random.levelup",1,1);for(int i=0;i<30;i++)mc.theWorld.spawnParticle("happyVillager",mc.thePlayer.posX+(mc.thePlayer.getRNG().nextDouble()-.5)*mc.thePlayer.width,mc.thePlayer.posY+mc.thePlayer.getRNG().nextDouble()*mc.thePlayer.height,mc.thePlayer.posZ+(mc.thePlayer.getRNG().nextDouble()-.5)*mc.thePlayer.width,(mc.thePlayer.getRNG().nextDouble()-.5)*.2,mc.thePlayer.getRNG().nextDouble()*.2,(mc.thePlayer.getRNG().nextDouble()-.5)*.2);}}
 @SubscribeEvent public void tick(TickEvent.ClientTickEvent e){if(e.phase==TickEvent.Phase.END&&ticks>=0&&++ticks>=40)ticks=-1;}
 @SubscribeEvent public void render(RenderGameOverlayEvent.Post e){if(e.type!=RenderGameOverlayEvent.ElementType.ALL||ticks<0)return;Minecraft mc=Minecraft.getMinecraft();float p=ticks+e.partialTicks;float appear=Math.min(1,p/5),fade=Math.min(1,(40-p)/10);float pulse=1+net.minecraft.util.MathHelper.sin(p*.55F)*.08F;int x=e.resolution.getScaledWidth()/2,y=e.resolution.getScaledHeight()/2;GL11.glPushMatrix();GL11.glPushAttrib(GL11.GL_ALL_ATTRIB_BITS);GL11.glTranslatef(x,y,500);GL11.glRotatef(net.minecraft.util.MathHelper.sin(p*.35F)*12,0,0,1);float scale=4*pulse*appear;GL11.glScalef(scale,scale,scale);GL11.glTranslatef(-8,-8,0);GL11.glEnable(GL11.GL_BLEND);GL11.glBlendFunc(GL11.GL_SRC_ALPHA,GL11.GL_ONE_MINUS_SRC_ALPHA);GL11.glColor4f(1,1,1,fade);RenderHelper.enableGUIStandardItemLighting();RenderItem.getInstance().renderItemAndEffectIntoGUI(mc.fontRenderer,mc.getTextureManager(),new ItemStack(ExplorationContent112.totemOfUndying),0,0);RenderHelper.disableStandardItemLighting();GL11.glPopAttrib();GL11.glPopMatrix();GL11.glColor4f(1,1,1,1);}
 public TotemActivationRenderer112(){}
}
